(1468112, 191448, 18197, '<td valign="top">I like the colors and flow of this very much. Feels like a ribbon contender to me.  I hope your photographer''s comments will tell us how you did this.</td>', 'I like the colors and flow of this very much. Feels like a ribbon contender to me.  I hope your photographer''s comments will tell us how you did this.', '2005-06-20 02:09:53.000000', NULL, 1),
(1468113, 191307, 18197, '<td valign="top">Beautifully done. Right out of the Alien movie tradition. One of only a few that lived up to the spirit of the challenge this week. Great job, feels like a ribbon contender to me. I hope your comments will tell us how you did it!</td>', 'Beautifully done. Right out of the Alien movie tradition. One of only a few that lived up to the spirit of the challenge this week. Great job, feels like a ribbon contender to me. I hope your comments will tell us how you did it!', '2005-06-20 02:10:20.000000', NULL, 1),
(1468114, 192343, 18197, '<td valign="top">Excellent subject choice and well executed. Composition is outstanding. The rest of the technical aspects are well done. Good luck in the voting.</td>', 'Excellent subject choice and well executed. Composition is outstanding. The rest of the technical aspects are well done. Good luck in the voting.', '2005-06-20 02:11:37.000000', NULL, 1),
