(1468349, 189512, 39243, '<td valign="top">lol - excellent - especially the smoke</td>', 'lol - excellent - especially the smoke', '2005-06-20 04:34:00.000000', NULL, 1),
(1468350, 192209, 9089, '<td valign="top">Figured there would be more infrareds in this challenge.  But seeing as yours is the only one, and tack sharp, looks fantastic.  My choice for top 3.  My only wish is that the tree would not be leaning ''out'' of the picture, instead leading into it, so as to keep your eyes on the picture instead of taking you out of it.</td>', 'Figured there would be more infrareds in this challenge.  But seeing as yours is the only one, and tack sharp, looks fantastic.  My choice for top 3.  My only wish is that the tree would not be leaning ''out'' of the picture, instead leading into it, so as to keep your eyes on the picture instead of taking you out of it.', '2005-06-20 04:34:10.000000', NULL, 1),
(1468351, 190722, 39243, '<td valign="top">I love the soft light -</td>', 'I love the soft light -', '2005-06-20 04:34:23.000000', NULL, 1),
(1468353, 192230, 9089, '<td valign="top">Gorgeous colors and composition.  I could dwell on this picture for a long time.  Hopefully the details are even more fascinating in larger pictures of it.</td>', 'Gorgeous colors and composition.  I could dwell on this picture for a long time.  Hopefully the details are even more fascinating in larger pictures of it.', '2005-06-20 04:35:19.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1468354, 190338, 9089, '<td valign="top">Beautiful Discus.  I think it is a good interpretation of the challenge.  The hand framing the fish helps to keep the focus.</td>', 'Beautiful Discus.  I think it is a good interpretation of the challenge.  The hand framing the fish helps to keep the focus.', '2005-06-20 04:36:10.000000', NULL, 1),
(1468355, 192410, 33352, '<td valign="top">Very effective, hope I don''t look like this in the future...8</td>', 'Very effective, hope I don''t look like this in the future...8', '2005-06-20 04:36:31.000000', NULL, 1),
(1468357, 191296, 9089, '<td valign="top">I think this is one of the most beautiful pictures in this challenge.  In saying that, I''m trying to fit it into the challenge itself, if it was more tied to the challenge would be a winner for sure.  7 from me</td>', 'I think this is one of the most beautiful pictures in this challenge.  In saying that, I''m trying to fit it into the challenge itself, if it was more tied to the challenge would be a winner for sure.  7 from me', '2005-06-20 04:37:36.000000', NULL, 1),
(1468360, 192157, 9089, '<td valign="top">Beautiful picture of St. Mary''s Basilica there in Krakow.  I''ve used the story of the trumpeter in sermons.</td>', 'Beautiful picture of St. Mary''s Basilica there in Krakow.  I''ve used the story of the trumpeter in sermons.', '2005-06-20 04:40:44.000000', NULL, 1),
(1468361, 191543, 33352, '<td valign="top">Well Done...9</td>', 'Well Done...9', '2005-06-20 04:42:04.000000', NULL, 1),
(1468366, 192485, 9089, '<td valign="top">Best of the ''other worldly'' landscapes.</td>', 'Best of the ''other worldly'' landscapes.', '2005-06-20 04:44:43.000000', NULL, 1),
(1468375, 192166, 39243, '<td valign="top">I wish I knew how to do this - real interesting I keep trying to get my brain around it.</td>', 'I wish I knew how to do this - real interesting I keep trying to get my brain around it.', '2005-06-20 04:49:53.000000', NULL, 1),
(1468376, 190988, 9089, '<td valign="top">Where''s the location for this?  I''ve seen this before (I think).  Definitely looks fantasy worldlike.  Almost a shame to see the modern building put into that scene.  The darkness of the top layer of clouds detracts a little from the picture itself, I would dodge it just a bit to not make it quite so dark, and give it a more even coloration with the rest of the sky.</td>', 'Where''s the location for this?  I''ve seen this before (I think).  Definitely looks fantasy worldlike.  Almost a shame to see the modern building put into that scene.  The darkness of the top layer of clouds detracts a little from the picture itself, I would dodge it just a bit to not make it quite so dark, and give it a more even coloration with the rest of the sky.', '2005-06-20 04:49:56.000000', NULL, 1),
(1468378, 191162, 33352, '<td valign="top">This is a very good image,with great contrast, but I am bemused that It appears to be more than than one image, blended, I hope to be proven wrong,so don''t be disqualified, I am giving this image a 10</td>', 'This is a very good image,with great contrast, but I am bemused that It appears to be more than than one image, blended, I hope to be proven wrong,so don''t be disqualified, I am giving this image a 10', '2005-06-20 04:52:12.000000', NULL, 1),
(1468381, 192314, 39243, '<td valign="top">looks like an explosion! neato!</td>', 'looks like an explosion! neato!', '2005-06-20 04:55:11.000000', NULL, 1),
(1468383, 192329, 39243, '<td valign="top">hehe</td>', 'hehe', '2005-06-20 04:55:27.000000', NULL, 1),
(1468386, 191564, 39243, '<td valign="top">neat concept I just am not so sure on the light in the BG. I would have personally rather not seen where the light was comming from. This is of course only my opinion. I don''t think my shot is this good.</td>', 'neat concept I just am not so sure on the light in the BG. I would have personally rather not seen where the light was comming from. This is of course only my opinion. I don''t think my shot is this good.', '2005-06-20 04:57:08.000000', NULL, 1),
(1468390, 191559, 39243, '<td valign="top">Awesome- Awesome-</td>', 'Awesome- Awesome-', '2005-06-20 04:57:55.000000', NULL, 1),
(1468397, 191162, 39243, '<td valign="top">I know this is being picky - but the foliage seems too much from our world. I think vines and drooping dark foliage would have been better. Having said that this is much better than mine and It is a great shot</td>', 'I know this is being picky - but the foliage seems too much from our world. I think vines and drooping dark foliage would have been better. Having said that this is much better than mine and It is a great shot', '2005-06-20 05:04:01.000000', NULL, 1),
(1468398, 191327, 9089, '<td valign="top">I''ve bumped this photo up twice...  It''s the one that keeps me coming back...  Started at 7, then to 9, then to 10.  Sharpness, details, colors are all fantastic.  Composition is good as well.  My only prayer is that the colors are natural and not photoshopped, but if they are, oh well, I''m voting as if they aren''t.  Good luck.</td>', 'I''ve bumped this photo up twice...  It''s the one that keeps me coming back...  Started at 7, then to 9, then to 10.  Sharpness, details, colors are all fantastic.  Composition is good as well.  My only prayer is that the colors are natural and not photoshopped, but if they are, oh well, I''m voting as if they aren''t.  Good luck.', '2005-06-20 05:08:13.000000', NULL, 1),
(1468400, 192447, 9089, '<td valign="top">Cute photo, I expected to see more of this kind of photo.  Couple little problems, first the dress has too many blown out highlights this causes me to stop looking at her cute face, but am drawn to the brightness.  Second is the large blades of grass to the bottom left of the picture, would be better to have gotten rid of them before taking the photo, then they wouldn''t be competing with the subject of the photo.  7</td>', 'Cute photo, I expected to see more of this kind of photo.  Couple little problems, first the dress has too many blown out highlights this causes me to stop looking at her cute face, but am drawn to the brightness.  Second is the large blades of grass to the bottom left of the picture, would be better to have gotten rid of them before taking the photo, then they wouldn''t be competing with the subject of the photo.  7', '2005-06-20 05:10:23.000000', NULL, 1),
(1468401, 192343, 9089, '<td valign="top">Definitely otherworldly.  Lighting works very well on this.  Seems like the face is a tad soft, but I do like the photo.  7</td>', 'Definitely otherworldly.  Lighting works very well on this.  Seems like the face is a tad soft, but I do like the photo.  7', '2005-06-20 05:11:27.000000', NULL, 1),
(1468402, 191559, 9089, '<td valign="top">Good ghostly image here.  I wish that the ghosty image had the same ''ghostiness'' from the head to the arm.  On second contemplation, maybe you were trying to show the light causing the true ethereal nature of the ghost to be revealed while the arm in darkness continues the ''reality'' of the dream.</td>', 'Good ghostly image here.  I wish that the ghosty image had the same ''ghostiness'' from the head to the arm.  On second contemplation, maybe you were trying to show the light causing the true ethereal nature of the ghost to be revealed while the arm in darkness continues the ''reality'' of the dream.', '2005-06-20 05:13:57.000000', NULL, 1),
(1468405, 192460, 9089, '<td valign="top">Seems like we''ve seen this beach before... What are the circles to the bottom left of her foot in the clouds?  Wait, I''m now guessing that they are supposed to be bubbles.  I see them on her dress.  It may be the limitation in the picture size, but at this size they look like imperfections (either bad clones or water spots).</td>', 'Seems like we''ve seen this beach before... What are the circles to the bottom left of her foot in the clouds?  Wait, I''m now guessing that they are supposed to be bubbles.  I see them on her dress.  It may be the limitation in the picture size, but at this size they look like imperfections (either bad clones or water spots).', '2005-06-20 05:17:02.000000', NULL, 1),
(1468407, 191303, 9089, '<td valign="top">Definitely think this is the best of the ''character'' shots in the challenge.  I do like the look of it.  I would clone out what look to be the 2 fingers, as they do not appear to be attached to the body, and add nothing to the photo.</td>', 'Definitely think this is the best of the ''character'' shots in the challenge.  I do like the look of it.  I would clone out what look to be the 2 fingers, as they do not appear to be attached to the body, and add nothing to the photo.', '2005-06-20 05:18:20.000000', NULL, 1),
(1468409, 192448, 9089, '<td valign="top">Definitely fits the challenge, but does seem to be a little soft at the focal point. 6</td>', 'Definitely fits the challenge, but does seem to be a little soft at the focal point. 6', '2005-06-20 05:22:12.000000', NULL, 1),
(1468411, 192189, 9089, '<td valign="top">I was thinking what does a periwinkle (shrub/flower) have to do with this picture, so I went and looked it up in the dictionary and found out that it was snails as well.  So thanks for improving my knowledge with this photo.  Intriguing rock textures with the snails add to the interest of the picture.  If the right hand side of the rock didn''t lead off the photo, this would score much higher.  6</td>', 'I was thinking what does a periwinkle (shrub/flower) have to do with this picture, so I went and looked it up in the dictionary and found out that it was snails as well.  So thanks for improving my knowledge with this photo.  Intriguing rock textures with the snails add to the interest of the picture.  If the right hand side of the rock didn''t lead off the photo, this would score much higher.  6', '2005-06-20 05:26:00.000000', NULL, 1),
(1468412, 192475, 9089, '<td valign="top">Beautiful gradiant in the sunset.  I just wish that it tied more closely to the theme.  If I go with your title of Atlantis, to make it fit in, I can''t imagine there being a shore with trees that close to the remnants of a destroyed civilization.  But I''ll give the benefit of the doubt.  6</td>', 'Beautiful gradiant in the sunset.  I just wish that it tied more closely to the theme.  If I go with your title of Atlantis, to make it fit in, I can''t imagine there being a shore with trees that close to the remnants of a destroyed civilization.  But I''ll give the benefit of the doubt.  6', '2005-06-20 05:28:15.000000', NULL, 1),
(1468413, 191570, 9089, '<td valign="top">The lighting on this toy? gives it the air of realism.  Do wish the left hand edge would be included in the photo and the light? in front of the right hand wing would be removed/cloned out. 6</td>', 'The lighting on this toy? gives it the air of realism.  Do wish the left hand edge would be included in the photo and the light? in front of the right hand wing would be removed/cloned out. 6', '2005-06-20 05:30:48.000000', NULL, 1),
(1468414, 192374, 9089, '<td valign="top">Good capture on this.  I like the colors in the wall, but I don''t really like the desaturation of the boy.  Also, he seems to be leaned back a little.  If he was standing straight so that his shirt wasn''t taking my focus out of the picture would help to improve the shot.  6</td>', 'Good capture on this.  I like the colors in the wall, but I don''t really like the desaturation of the boy.  Also, he seems to be leaned back a little.  If he was standing straight so that his shirt wasn''t taking my focus out of the picture would help to improve the shot.  6', '2005-06-20 05:32:32.000000', NULL, 1),
(1468416, 191162, 24983, '<td valign="top">this is anexcellent image although not original it certainly is fantasy 9</td>', 'this is anexcellent image although not original it certainly is fantasy 9', '2005-06-20 05:35:35.000000', NULL, 1),
