INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1469640, 190897, 37719, '<td valign="top">I like this shot and find it very interesting.  I find the upper part a little distracting with the color change (looks red - possible reflection?).  Could have been a little brighter.  9</td>', 'I like this shot and find it very interesting.  I find the upper part a little distracting with the color change (looks red - possible reflection?).  Could have been a little brighter.  9', '2005-06-20 18:39:01.000000', NULL, 1),
