(1469809, 192409, 38997, '<td valign="top">I love the monochromatic colors</td>', 'I love the monochromatic colors', '2005-06-20 19:39:15.000000', NULL, 1),
(1469810, 190482, 33947, '<td valign="top">I very much like your idea for meeting the challenge, but, the result hits me as too cluttered and hard to make out. Points for trying, though!</td>', 'I very much like your idea for meeting the challenge, but, the result hits me as too cluttered and hard to make out. Points for trying, though!', '2005-06-20 19:39:32.000000', NULL, 1),
