(1469889, 190929, 33947, '<td valign="top">Did you freeze Ken?! I''m not big on toys in pictures, but, the lighting effect is pretty neat...especially the green part. Nice try.</td>', 'Did you freeze Ken?! I''m not big on toys in pictures, but, the lighting effect is pretty neat...especially the green part. Nice try.', '2005-06-20 20:26:18.000000', NULL, 1),
(1469892, 190841, 33947, '<td valign="top">I''m not sure about this meeting the challenge, but that said, I love it as an abstract. The repetition of the masts is effective, and I love the orange background. Makes for a surreal effect.</td>', 'I''m not sure about this meeting the challenge, but that said, I love it as an abstract. The repetition of the masts is effective, and I love the orange background. Makes for a surreal effect.', '2005-06-20 20:28:36.000000', NULL, 1),
(1469893, 191230, 33947, '<td valign="top">Made me smile. Clever.</td>', 'Made me smile. Clever.', '2005-06-20 20:29:54.000000', NULL, 1),
(1469897, 190722, 24183, '<td valign="top">Love this photo, great job.  I really like the crop and wings that are highlighted.</td>', 'Love this photo, great job.  I really like the crop and wings that are highlighted.', '2005-06-20 20:32:36.000000', NULL, 1),
(1469900, 192467, 33947, '<td valign="top">You''re right! That IS Thumbalina''s garden! I like the softness of the photo...adds to the mood, and I like all the curvy sprout-like things. Personally, I wish it was in color. This particular black and white treatment doesn''t move me. That said, I still do like the photo.</td>', 'You''re right! That IS Thumbalina''s garden! I like the softness of the photo...adds to the mood, and I like all the curvy sprout-like things. Personally, I wish it was in color. This particular black and white treatment doesn''t move me. That said, I still do like the photo.', '2005-06-20 20:34:03.000000', NULL, 1),
(1469901, 192329, 33947, '<td valign="top">Like the lighting and the smoke.</td>', 'Like the lighting and the smoke.', '2005-06-20 20:34:36.000000', NULL, 1),
(1469906, 189175, 33947, '<td valign="top">Hard to figure out what''s going on here. Sorry.</td>', 'Hard to figure out what''s going on here. Sorry.', '2005-06-20 20:37:00.000000', NULL, 1),
(1469908, 192313, 33947, '<td valign="top">I like the treatment you did of the blue shells. Nice rich colors. Overall, though, I wish the clarity were a better, and that I could make it out easier.</td>', 'I like the treatment you did of the blue shells. Nice rich colors. Overall, though, I wish the clarity were a better, and that I could make it out easier.', '2005-06-20 20:39:29.000000', NULL, 1),
(1469913, 191033, 33947, '<td valign="top">Creative idea. The frame is a bit cluttered for me, BUT, that is one neat rocker!!! Love him. Points for trying something different.</td>', 'Creative idea. The frame is a bit cluttered for me, BUT, that is one neat rocker!!! Love him. Points for trying something different.', '2005-06-20 20:41:32.000000', NULL, 1),
(1469916, 192361, 33947, '<td valign="top">I like the simplicity of this. It''s very basic, and very effective. Neat lighting. I hope you do well.</td>', 'I like the simplicity of this. It''s very basic, and very effective. Neat lighting. I hope you do well.', '2005-06-20 20:42:45.000000', NULL, 1),
(1469918, 191050, 6667, '<td valign="top">Flower power!  Neat! BOL</td>', 'Flower power!  Neat! BOL', '2005-06-20 20:42:53.000000', NULL, 1),
(1469919, 192089, 33947, '<td valign="top">This is a bit TOO much out of focus to be "dreamy"  to me. It''s hard to look at, and hurts the eyes.</td>', 'This is a bit TOO much out of focus to be "dreamy"  to me. It''s hard to look at, and hurts the eyes.', '2005-06-20 20:44:07.000000', NULL, 1),
