(1470530, 191162, 31443, '<td valign="top">Where did you get this guy??? Love the colors...</td>', 'Where did you get this guy??? Love the colors...', '2005-06-21 03:51:39.000000', NULL, 1),
(1470532, 192046, 31443, '<td valign="top">Don''t know about fantasy since this is a real fact but beautiful nonetheless and the photo is great!</td>', 'Don''t know about fantasy since this is a real fact but beautiful nonetheless and the photo is great!', '2005-06-21 03:52:34.000000', NULL, 1),
