(1476583, 192329, 368, '<td valign="top">ahh dragons - sure would think of fantasy .. just wish this little guy was more in focus .. but i like th concept and he''s cool cause he''s red :)</td>', 'ahh dragons - sure would think of fantasy .. just wish this little guy was more in focus .. but i like th concept and he''s cool cause he''s red :)', '2005-06-22 20:16:32.000000', NULL, 1),
(1476602, 192460, 368, '<td valign="top">what a nice capture and timing .. the detail is right no .. .definitly free spirited - i guess that can be in anyone''s fantasy world :)</td>', 'what a nice capture and timing .. the detail is right no .. .definitly free spirited - i guess that can be in anyone''s fantasy world :)', '2005-06-22 20:20:32.000000', NULL, 1),
(1476610, 192483, 368, '<td valign="top">i really wish this was a little more in focus ... but you got me singing ... "i''d like to be... under the sea ... " :)</td>', 'i really wish this was a little more in focus ... but you got me singing ... "i''d like to be... under the sea ... " :)', '2005-06-22 20:21:44.000000', NULL, 1),
