(1480210, 192361, 4767, '<td valign="top">AWESOME photo!  That sky is incredible -   it may be ever-so-slightly oversharpened, as the demarcation from land to sky shows as a white line on my monitor.  7</td>', 'AWESOME photo!  That sky is incredible -   it may be ever-so-slightly oversharpened, as the demarcation from land to sky shows as a white line on my monitor.  7', '2005-06-24 01:39:21.000000', NULL, 1),
