INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1530979, 190427, 28742, '<td valign="top">Very interesting looking building. Nicely composed and intersting angles. Only suggestion - better lighting on the face of the building maybe through post-proc.</td>', 'Very interesting looking building. Nicely composed and intersting angles. Only suggestion - better lighting on the face of the building maybe through post-proc.', '2005-07-12 21:01:58.000000', NULL, 0),
(1534425, 190427, 8891, '<td valign="top">Like the image and the architecture very much in this. I am not a fan of the dodge and burn of the sky business as I am not able it to do it well. But may certainly increase the drama. But to the archicture, I was thinking the same as Ken (kpriest) when I looked at it and think that more lighting on the front would a good idea. Not sure about the processing part, you just need some good sun at a different part of the day. Great angle and I liked the repitition of the curve on the left to the top of the taller building on the right. It looks like you got some interesting reflections on the front to which would be helped by the brightening as well.</td>', 'Like the image and the architecture very much in this. I am not a fan of the dodge and burn of the sky business as I am not able it to do it well. But may certainly increase the drama. But to the archicture, I was thinking the same as Ken (kpriest) when I looked at it and think that more lighting on the front would a good idea. Not sure about the processing part, you just need some good sun at a different part of the day. Great angle and I liked the repitition of the curve on the left to the top of the taller building on the right. It looks like you got some interesting reflections on the front to which would be helped by the brightening as well.', '2005-07-14 00:22:49.000000', NULL, 0),
